'use client'

import { useEffect, useState } from 'react'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import api from '@/lib/api'

function ResultRow({ item }) {
  return (
    <li className="rounded-lg border border-border p-3 text-sm">
      <p className="font-semibold">{item.id} â€” {item.success ? 'Completed' : 'Failed'}</p>
      {item.success ? (
        <div className="mt-2 space-y-2">
          <p><strong>First draft:</strong> {item.data.firstDraft}</p>
          <p><strong>Selected reply:</strong> {item.data.selectedReply}</p>
          <p><strong>History review:</strong> {item.data.decisions?.history} · <strong>Conflict review:</strong> {item.data.decisions?.conflict}</p>
          <p><strong>Pending cases created:</strong> {item.data.caseIDs.length}</p>
          <p><strong>Approved test examples retrieved:</strong> {item.data.approvedExampleIDs.length}</p>
        </div>
      ) : <p className="mt-2 text-destructive">{item.error}</p>}
    </li>
  )
}

export default function ReviewSimulationPanel({ canWrite, onCasesCreated }) {
  const [fixtures, setFixtures] = useState([])
  const [selectedId, setSelectedId] = useState('')
  const [customerMessage, setCustomerMessage] = useState('')
  const [draftOverride, setDraftOverride] = useState('')
  const [running, setRunning] = useState(false)
  const [progress, setProgress] = useState('')
  const [error, setError] = useState('')
  const [results, setResults] = useState([])

  useEffect(() => {
    if (!canWrite || process.env.NODE_ENV !== 'development') return
    let active = true
    api.get('/api/sms-reply-reviews/simulate/cases').then((result) => {
      if (!active) return
      if (!result.success) {
        setError(result.error || 'Local simulation is unavailable.')
        return
      }
      const cases = result.data?.cases || []
      setFixtures(cases)
      if (cases.length) {
        setSelectedId(cases[0].id)
        setCustomerMessage(cases[0].customerMessage)
        setDraftOverride(cases[0].draftOverride)
      }
    })
    return () => { active = false }
  }, [canWrite])

  if (!canWrite || process.env.NODE_ENV !== 'development') return null

  const selected = fixtures.find((item) => item.id === selectedId)
  const chooseCase = (id) => {
    const next = fixtures.find((item) => item.id === id)
    if (!next) return
    setSelectedId(id)
    setCustomerMessage(next.customerMessage)
    setDraftOverride(next.draftOverride)
    setResults([])
  }

  const sendCase = async (item, useHistoricalDraft) => {
    const result = await api.post('/api/sms-reply-reviews/simulate', {
      fixtureId: item.id,
      customerMessage: item.customerMessage,
      priorMessages: item.priorMessages,
      draftOverride: useHistoricalDraft ? item.draftOverride : '',
    })
    return { id: item.id, success: result.success, data: result.data, error: result.error }
  }

  const runSelected = async (useHistoricalDraft) => {
    if (!selected || !customerMessage.trim()) return
    setRunning(true)
    setError('')
    setProgress('Running selected caseâ€¦')
    const item = { ...selected, customerMessage, draftOverride }
    const outcome = await sendCase(item, useHistoricalDraft)
    setResults([outcome])
    setProgress('')
    setRunning(false)
    if (outcome.success) onCasesCreated()
  }

  const runAll = async () => {
    setRunning(true)
    setError('')
    setResults([])
    const completed = []
    for (const [index, item] of fixtures.entries()) {
      setProgress(`Running ${index + 1} of ${fixtures.length}: ${item.id}`)
      completed.push(await sendCase(item, true))
      setResults([...completed])
    }
    setProgress('')
    setRunning(false)
    onCasesCreated()
  }

  return (
    <section className="space-y-4 rounded-xl border border-border bg-card p-4 shadow-sm" aria-label="Local review simulation">
      <div>
        <h2 className="font-semibold">Local review simulation</h2>
        <p className="text-sm text-muted-foreground">No real SMS, booking, or payment is made. These cases stay separate from live RAG. Historical cases use their saved prompts, so All Branches is fine.</p>
      </div>
      {error && <p role="alert" className="text-sm text-destructive">{error} Set ENABLE_SMS_REVIEW_SIMULATION=true on the local backend and restart it.</p>}
      <label className="block space-y-1 text-sm">
        <span className="font-medium">Historical case (11 history, 3 conflict)</span>
        <select className="w-full rounded-lg border border-border bg-background p-2" value={selectedId} onChange={(event) => chooseCase(event.target.value)} disabled={running || !fixtures.length}>
          {fixtures.map((item) => <option key={item.id} value={item.id}>{item.id} ({item.type})</option>)}
        </select>
      </label>
      <label className="block space-y-1 text-sm">
        <span className="font-medium">Customer message</span>
        <Textarea value={customerMessage} onChange={(event) => setCustomerMessage(event.target.value)} disabled={running} rows={2} />
      </label>
      <label className="block space-y-1 text-sm">
        <span className="font-medium">Historical first draft</span>
        <Textarea value={draftOverride} onChange={(event) => setDraftOverride(event.target.value)} disabled={running} rows={3} />
      </label>
      <div className="flex flex-wrap gap-2">
        <Button type="button" onClick={() => runSelected(true)} disabled={running || !selected || !draftOverride.trim()}>Test selected historical draft</Button>
        <Button type="button" variant="outline" onClick={() => runSelected(false)} disabled={running || !selected}>Preview first agent + reviewers</Button>
        <Button type="button" variant="outline" onClick={runAll} disabled={running || fixtures.length !== 14}>Run all 14 historical drafts</Button>
      </div>
      {progress && <p role="status" className="text-sm">{progress}</p>}
      {results.length > 0 && <ul className="space-y-2">{results.map((item) => <ResultRow key={item.id} item={item} />)}</ul>}
    </section>
  )
}
